o=O("js-code/J04ObjectOperations.js"),po=O("js-code/J05ThisBinding.js"),vo=O("js-code/J06PrototypeClass.js"),Eo=O("js-code/J07PromiseCombinators.js"),fo=O("js-code/J08EventLoop.js"),Ao=O("js-code/J09Modules.js"),co=O("js-code/J10EventDelegation.js"),Po=O("js-code/J11AsyncAwait.js"),To=O("js-code/J12IteratorsGenerators.js"),Lo=O("js-code/J13ProxyReflect.js"),Do=O("js-code/J14MapSetWeakRef.js"),Ro=O("js-code/J15RegExp.js"),Oo=O("js-code/J16ErrorHandling.js"),Io=O("js-code/J17OptionalNullish.js"),Vo=O("js-code/J18HigherOrder.js"),go=O("js-code/J19TemplateLiterals.js"),yo=O("js-code/J20JsonClone.js"),So=O("js-code/J21PropertyDescriptors.js"),bo=O("js-code/J22Symbol.js"),ho=O("js-code/J23StringIntl.js"),Co=O("js-code/J24LogicalBitwise.js"),jo=O("js-code/J25FetchApi.js"),xo=O("js-code/J26WebStorage.js"),Jo=O("js-code/J27WebSocket.js"),wo=O("js-code/J28AbortController.js"),$o=[{id:"J_01",title:"原始类型、引用类型与类型转换",navTitle:"类型与相等",category:"语言基础",path:"/javascript/j-1/types-equality",summary:"掌握 7 种原始类型与引用类型的 typeof 行为、显式转换（Number/String/Boolean）、隐式转换规则，以及 == 与 === 的经典差异。",demo:null,demoComponent:ie,code:mo,language:"javascript",principle:'JavaScript 是动态类型语言，运算时会按规范触发隐式类型转换。typeof 对 null 返回 "object" 是历史遗留 bug；除函数外，引用类型的 typeof 统一为 "object"，判断数组须用 Array.isArray()。显式转换用 Number()、String()、Boolean()；falsy 值共有 false、0、-0、0n、""、null、undefined、NaN 八种，其余值（含空数组、空对象）都是 truthy。== 会先做类型转换再比较，=== 要求类型与值都一致。',flow:["用 typeof 识别值在运行时的类型，注意 function 与 null 两个例外。","在输入边界显式调用 Number()/String()/Boolean() 转换，避免依赖隐式规则。","始终用 === 与 !== 做相等比较。","用 Number.isNaN()、Array.isArray()、Object.is() 处理特殊边界。"],notes:['typeof null → "object" 是语言早期实现的遗留问题。',"全局 isNaN 会先把参数转成数字再判断，判断 NaN 须用 Number.isNaN()。",'falsy 值包括 false、0、-0、0n、""、null、undefined、NaN，空数组和空对象都是 truthy。',"Object.is() 认为 NaN 与自身相等，且能区分 +0 与 -0。"],problem:'解决"表单输入、API 参数比较时为什么出现反直觉结果，以及如何正确识别和转换 JavaScript 类型"的问题。'},{id:"J_02",title:"词法作用域与闭包",navTitle:"作用域与闭包",category:"语言基础",path:"/javascript/j-2/closure",summary:"用购物车计数器理解函数如何保留创建时的变量环境。",demo:null,demoComponent:_e,code:so,language:"javascript",principle:"函数能访问哪些变量由代码书写位置决定，而不是调用位置，这就是词法作用域；内部函数被当作返回值转交到外部后，仍持有对创建它的词法环境的引用，因此能继续访问并修改其中的变量，这个“内部函数 + 词法环境”的组合就是闭包。被闭包捕获的变量不在函数返回时释放，而是随引用存活在内存中，这正是它能封装私有状态的原因。",flow:["外层函数在自己的词法环境中创建局部状态（如购物车计数）。","把能够读写该状态的内部函数作为返回值交给外部。","外部每调用一次返回的函数，都继续读写同一份词法环境。","在浏览器内存面板确认被闭包引用的数据持续存活。"],notes:["每次调用外层函数都会创建独立的词法环境，各自的计数互不干扰。","闭包适合封装外部无法直接读写的私有状态。","长期被闭包持有的大对象会阻止 GC 回收，用完后应及时解除引用。","循环中用 var 注册回调会共享同一个变量，改用 let 或闭包工厂为每轮保存独立副本。"],problem:'解决"事件回调为什么还能读到外层函数早已返回的变量，以及如何用它封装只暴露接口、不暴露数据的私有状态"的问题。'},{id:"J_03",title:"数组的不可变转换流水线",navTitle:"数组方法",category:"集合与数据",path:"/javascript/j-3/array-pipeline",summary:"用 filter 筛选课程、toSorted 排序，组合成课程的不可变搜索转换流水线。",demo:null,demoComponent:Ee,code:_o,language:"javascript",principle:"数组处理可拆成筛选、映射等可组合的步骤；其中 filter、toSorted 等返回新数组而不改动原数组，链式调用形成只读的转换流水线，避免通过共享引用意外修改状态，也是 React / Vue 不可变更新范式的基础。掌握 filter、map、toSorted 等非破坏性方法的边界，是不变数据实践的第一步。",flow:["用 filter 把结果缩小到标题匹配关键词的课程。","把筛选结果传给 toSorted，按传入的比较函数得到评分降序的新数组。","链式组合多个返回新数组的方法，使流水线可预测且不改原数组。","对比 sort 与 toSorted，确认原数组在后者调用后保持不变。"],notes:["toSorted 返回排序后的新数组，区别于直接修改原数组的 sort（ES2023）。","map 用于转换元素、forEach 用于执行副作用，不要把 map 当副作用工具。","流水线全程不改原数组，其引用可被安全缓存与复用。","reduce 适合把多条处理步骤收敛为单个结果，但嵌套过深时拆成多步更可读。"],problem:'解决"列表搜索、筛选、排序时如何组合出可读且不改动原始数据的处理流水线"的问题。'},{id:"J_04",title:"对象、解构与展开语法",navTitle:"对象操作",category:"集合与数据",path:"/javascript/j-4/object-operations",summary:"通过用户资料更新掌握属性访问、解构、剩余与浅拷贝。",demo:null,demoComponent:Pe,code:ao,language:"javascript",principle:"解构按属性名或数组位置提取值，剩余语法把未被提取的字段收集进新对象，展开语法则把原对象可枚举的自有属性逐一复制到新对象。三者都只做浅层操作：只有第一层是新的，嵌套对象仍与被复制对象共享引用，因此局部更新时必须沿更新路径逐层用展开语法创建新对象，才能保证原数据不被意外修改。",flow:["从源对象解构出需要的字段，用剩余语法收集其余字段。","通过展开语法把剩余字段与新的覆盖值合并进新对象。","保持原对象不变，用新引用承接更新结果。","更新嵌套字段时沿路径逐层展开，验证原对象仍未被修改。"],notes:["浅拷贝下嵌套对象仍共享引用，深层更新需逐层创建新对象。","同名属性按展开位置决定覆盖顺序，后展开的替换先展开的。","需要完整深拷贝时再考虑 structuredClone，简单浅拷贝用展开即可。","更新前用 Object.is 对比新旧引用，确认确实产生了新对象。"],problem:'解决"局部更新用户资料时如何安全读取字段，并在不修改原对象的前提下得到更新结果"的问题。'},{id:"J_05",title:"函数调用方式与 this 绑定",navTitle:"this 绑定",category:"对象模型",path:"/javascript/j-5/this-binding",summary:"比较方法调用、脱离对象调用与 call 显式绑定。",demo:null,demoComponent:Re,code:po,language:"javascript",principle:"普通函数的 this 在调用时才确定，取决于调用表达式本身（方法调用指向调用者，独立调用在严格模式下为 undefined），而箭头函数捕获定义时所在函数作用域的 this，不随调用方式改变；call、apply、bind 可显式指定普通函数的接收者。",flow:["先看函数实际的调用表达式，判断是否以“对象.方法()”形式调用。","方法一旦被脱离对象独立调用，this 就不再指向原对象。","用 call 显式指定接收者，或在回调场景用箭头函数保持外层 this。","把方法改为箭头函数后再以回调形式调用，验证 this 是否按预期捕获。"],notes:["this 不指向函数定义时所在的“父对象”，只由调用方式决定。","严格模式下独立调用普通函数，this 为 undefined；非严格模式会指向全局对象。","类方法作为回调单独传参同样会丢失绑定，需用箭头函数或 bind 修正。","箭头函数的 this 在定义时锁定，之后无法再用 call/apply 改变。"],problem:'解决"把对象方法交给 setTimeout、事件监听等回调后 this 指向为何改变，以及如何稳定绑定"的问题。'},{id:"J_06",title:"原型链、class 与继承",navTitle:"原型与类",category:"对象模型",path:"/javascript/j-6/prototype-class",summary:"通过课程模型理解实例属性、共享方法与原型继承。",demo:null,demoComponent:ge,code:vo,language:"javascript",principle:"对象通过内部 [[Prototype]] 链接查找属性，整条链上的方法都可以被实例共享；class 提供更清晰的构造与继承语法，但底层依然是基于原型的委托机制，理解这点才能解释属性遮蔽、原型链查询与 instanceof 的工作方式。把方法放在原型上共享、把字段留成实例自己的，是使用对象时的基本分工。",flow:["构造函数初始化实例自身的字段（如 title、hours）。","实例方法定义在 prototype 上，被所有实例共享，节省内存。","extends 把子类原型链接到父类，super 调用父类同名方法。","在原型上添加一个方法，验证所有实例同步获得该能力。"],notes:["优先组合而非过深继承，组合更灵活、副作用更少。","私有字段可使用 #name 语法，外部无法直接访问。","Object.create 与 Object.setPrototypeOf 可手动操控原型关系。","调试时可用 Object.getPrototypeOf 沿链向上确认方法定义在哪一层。"],problem:'解决"JavaScript 对象如何共享行为以及 class 的底层机制"的问题。'},{id:"J_07",title:"Promise 组合与并发请求",navTitle:"Promise 并发",category:"异步机制",path:"/javascript/j-7/promise-combinators",summary:"用 Promise.all 并发加载看板数据，并比较常用组合器语义。",demo:null,demoComponent:Ce,code:Eo,language:"javascript",principle:"Promise 表示一个未来会落定（fulfilled 或 rejected）的结果；并发组合器并行启动多个异步任务并按不同策略聚合：Promise.all 全部成功才整体成功、allSettled 等全部结束并保留各自结果、race 取最先落定者、any 取最先成功者。",flow:["把互不依赖的任务同时发起，避免串行等待。","按业务对失败的容忍度选择 all / allSettled / any 等组合器。","对聚合结果统一解构取值，并在失败分支处理异常。","制造一个失败请求，对比 all 与 allSettled 的结果差异。"],notes:["Promise.all 在首个 reject 时立即整体拒绝，但其余任务仍会继续执行。","Promise.any 在全部失败时才以 AggregateError 拒绝。","高并发仍要考虑接口限流与服务端承载能力。","race 常用于超时竞争：与超时 Promise 组合，先落定者决定结果。"],problem:'解决"多个互不依赖的异步请求如何并发发起，并依据失败容忍度选择 all、allSettled、any 等组合器语义"的问题。'},{id:"J_08",title:"事件循环、任务与微任务",navTitle:"事件循环",category:"异步机制",path:"/javascript/j-8/event-loop",summary:"观察同步代码、Promise 微任务和定时器任务的执行顺序。",demo:null,demoComponent:we,code:fo,language:"javascript",principle:"调用栈清空后，事件循环会先清空整个微任务队列（Promise.then、queueMicrotask、MutationObserver），再取出下一个宏任务（如定时器回调）执行；浏览器若到帧时机，绘制一般发生在宏任务之间，理解这一顺序才能解释异步日志为何不同于书写顺序。",flow:["执行当前脚本中的同步代码，建立调用栈。","调用栈清空后清空微任务队列中的全部回调。","渲染（如果到了帧时机），再取出下一个宏任务执行。","分别打印同步代码、then 与 setTimeout 的日志，验证输出顺序。"],notes:["大量微任务也会阻塞渲染，要控制单次微任务工作量。","setTimeout(fn, 0) 不代表立即执行，最小延迟受宏任务调度影响。","Node.js 的 process.nextTick 优先级高于 Promise 微任务。","async 函数中 await 之前的代码同步执行，await 之后的部分进入微任务。"],problem:'解决"同步日志、Promise.then 与 setTimeout 的输出顺序为何与书写顺序不一致"的问题。'},{id:"J_09",title:"ES Modules 与动态导入",navTitle:"模块化",category:"模块与浏览器",path:"/javascript/j-9/modules",summary:"掌握静态 import/export、模块作用域和 import() 按需加载。",demo:null,demoComponent:We,code:Ao,language:"javascript",principle:"ES Module 具有独立作用域与静态依赖结构：import/export 在编译期就确定依赖图，导出是实时绑定，打包器据此做 Tree Shaking；动态 import() 返回 Promise，把低频功能拆成独立 chunk 按需拉取，是路由懒加载与首屏优化的标准手段。",flow:["用具名或默认导出声明模块的公共接口。","对首屏必需的依赖使用静态 import，便于打包器静态分析与 tree shaking。","对低频模块用动态 import() 按需加载，返回 Promise 并处理加载状态。","用打包分析工具确认动态 import() 的模块被拆成独立 chunk。"],notes:["ES Module 默认运行于严格模式。","顶层 await 只能在模块顶层使用，Node 端需为 ES Module 环境。","注意避免环形依赖在初始化阶段读取到未定义的值。","import 是只读绑定：模块内导出的变量更新后，导入方能看到最新值。"],problem:'解决"项目模块边界混乱、打包体积膨胀时，如何用静态 import 划定依赖、用动态 import() 把低频功能拆出首屏"的问题。'},{id:"J_10",title:"DOM 事件传播与事件委托",navTitle:"事件委托",category:"模块与浏览器",path:"/javascript/j-10/event-delegation",summary:"用课程列表理解捕获、冒泡、target 与 currentTarget。",demo:null,demoComponent:Ke,code:co,language:"javascript",principle:"DOM 事件经历捕获（capture）、目标（target）和冒泡（bubble）三个阶段，事件委托利用冒泡在稳定的父节点统一监听，再通过 closest() 或匹配选择器判断真实交互目标，动态列表也能高效工作。相比为每个子节点单独绑定，委托把监听器数量从 N 降到 1，新增节点也无需重新挂载。",flow:["在稳定的父容器注册一个冒泡阶段的 click 监听器。","用 event.target.closest(选择器) 从实际触发元素向上寻找匹配项。","通过 dataset 读取 data-* 属性并执行对应分支行为。","为列表动态插入新行，验证无需重新绑定即可响应点击。"],notes:["不是所有事件都会冒泡（如 focus、blur、scroll），必要时改用捕获阶段。","closest 会一直向上查到 document，使用时要结合委托容器判断是否误匹配。","委托显著减少监听器数量，且对动态增删的子节点天然生效。","点击容器自身空白区域时 closest 可能命中容器本身，处理前应确认目标范围。"],problem:'解决"列表项频繁增删时如何减少监听器数量，并让新增节点自动拥有交互能力"的问题。'},{id:"J_11",title:"async/await 与异步流控",navTitle:"async/await",category:"异步机制",path:"/javascript/j-11/async-await",summary:"用 async 函数和 await 表达串行与并发加载，掌握异步错误处理。",demo:null,demoComponent:et,code:Po,language:"javascript",principle:"async 函数总是返回 Promise，await 会暂停该函数直到 Promise 落定并取出结果；串行用 for...of 逐个 await，并发用 Promise.all 同时发起再一起等待，配合 try/catch/finally 统一处理错误与清理。",flow:["用 async 声明异步函数，函数体可整体 await。","串行需求用 for...of 逐个 await，并发热点用 Promise.all 同时发起。","用 try/catch/finally 捕获 await 链上的拒绝并执行清理。","用时间戳对比串行与并发执行的总耗时差异。"],notes:["await 只能在 async 函数内或 ES Module 顶层使用。","串行总耗时约为各步之和，并发约为最慢一步；实际并发仍要留意接口限流。","async 函数返回的 Promise 若无人处理，函数内部未捕获的异常会变成未处理的拒绝，调用方仍需 catch。","循环中直接 await 会退化为串行，需要并发时先收集 Promise 数组再统一等待。"],problem:'解决"如何用同步写法组织异步流程，并按依赖关系选择串行或并发策略"的问题。'},{id:"J_12",title:"迭代协议与生成器",navTitle:"迭代器与生成器",category:"集合与数据",path:"/javascript/j-12/iterators-generators",summary:"用生成器逐步产出课程列表，理解迭代协议和 yield 通信。",demo:null,demoComponent:mt,code:To,language:"javascript",principle:'迭代器协议要求 next() 返回 { value, done }；生成器函数用 yield 暂停执行、下次 next() 恢复，并支持通过 next(value) 向生成器回传数据，以及用 yield* 把产出委托给其他可迭代对象。把"逐个取值"与"何时结束"拆开来定义，是惰性序列与自定义迭代协议的共同基础。',flow:["实现 [Symbol.iterator] 让对象可被 for...of 惰性消费。","用 function* 配合 yield 创建生成器，yield 处暂停、next() 恢复。","用 next(value) 把值回传给上一个 yield 表达式，实现双向通信。","用 for...of 消费自定义迭代器，确认输出顺序与终止时机。"],notes:["for...of、展开语法、解构等都依赖迭代协议。","yield* 把当前生成器委托给另一个可迭代对象，逐个转发其产出。","生成器调用后函数体不会立即执行，只有第一次 next() 才运行到第一个 yield。","生成器一旦 return 或抛出异常，后续 next() 都得到 done: true，无法恢复。"],problem:'解决"大型或无限序列如何惰性产出，以及自定义对象如何接入 for...of 等迭代协议"的问题。'},{id:"J_13",title:"Proxy 与 Reflect",navTitle:"Proxy 与 Reflect",category:"对象模型",path:"/javascript/j-13/proxy-reflect",summary:"用 Proxy 拦截对象操作实现响应式验证和数据追踪。",demo:null,demoComponent:Et,code:Lo,language:"javascript",principle:"Proxy 用 new Proxy(target, handler) 包装目标对象并拦截 get/set/has/deleteProperty 等基本操作；Reflect 提供与 Proxy 陷阱一一对应的默认行为，转发时可以正确处理原型链、this 绑定和返回值，是实现响应式、ORM、校验库的核心原语。",flow:["用 new Proxy 包装需要增强的目标对象。","在对应的陷阱（trap）中执行自定义逻辑。","通过 Reflect 对应的方法转发默认行为，保证语义一致。","读取一个不存在的属性，验证 get 陷阱的拦截日志按预期输出。"],notes:["Proxy 不能代理对象的内部槽位（如 Date 的时间戳）。","Vue 3 响应式系统底层就是基于 Proxy 的依赖收集与触发。","深层代理需要递归包装，回收时也要逐层释放。","陷阱中若忘记转发对应操作，目标对象的默认行为会失效。"],problem:'解决"如何透明拦截和增强对象行为，同时保持默认语义与响应式追踪"的问题。'},{id:"J_14",title:"Map、Set 与弱引用",navTitle:"Map/Set/WeakRef",category:"集合与数据",path:"/javascript/j-14/map-set-weakref",summary:"用 Set 去重、Map 关联数据、WeakMap 绑定 DOM 元数据。",demo:null,demoComponent:Rt,code:Do,language:"javascript",principle:"Map 允许任意类型做键且保持插入顺序，Set 保证值唯一，都提供了普通对象和数组不具备的语义；WeakMap/WeakSet 的键是弱引用，键被回收时条目自动消失，不会阻止垃圾回收，适合给 DOM 节点或实例关联临时元数据，但不支持遍历与 size。",flow:["用 Set 收集不重复标签。","用 Map 建立对象到数据的映射。","用 WeakMap 给 DOM 元素附加私有数据。","用同一个对象作为 Map 键读取数据，验证引用相等才命中。"],notes:["WeakMap 的键不可枚举，且仅在键没有其他强引用时才允许回收。","GC 时机不可预测，WeakRef 与 FinalizationRegistry 不适合承载关键业务逻辑。","以对象为键时 Map 不会像普通对象那样把键字符串化，因此不会互相覆盖。","需要按插入顺序遍历或频繁增删键时，Map 比普通对象更合适。"],problem:'解决"何时用 Map/Set 替代对象和数组，以及如何用弱引用字典避免内存泄漏"的问题。'},{id:"J_15",title:"正则表达式与模式匹配",navTitle:"正则表达式",category:"语言基础",path:"/javascript/j-15/regexp",summary:"用正则匹配手机号、邮箱、价格与日期，掌握捕获组和前后断言。",demo:null,demoComponent:bt,code:Ro,language:"javascript",principle:"正则表达式用模式匹配字符串；字符类、量词、捕获组与前后断言组合出精确规则，test() 用于验证、exec() 提取单次匹配（含命名组）、matchAll() 与 replace() 处理所有匹配和替换。修饰符（g、i、m、s、u）控制匹配范围，带 g 的正则还会在 lastIndex 上保留上次匹配位置。",flow:["用字符类与量词描述匹配模式（如手机号 ^1[3-9] 开头加 9 位数字）。","用捕获组与命名组（?<name>）提取子串。","用正/负前瞻与后行断言限定上下文而不消耗字符。","用命名捕获组提取片段，并通过 groups 对象按名字取值。"],notes:["带 g 标志的正则多次 exec/test 会因 lastIndex 前进产生不同结果。","复杂校验建议拆成多个边界清晰的正则分别判断。","把用户输入拼接进正则模式前必须转义特殊字符，否则会改变匹配语义甚至造成性能灾难。","量词尽量写得具体（如 [0-9]{4}），避免 .* 在大文本上回溯爆炸。"],problem:'解决"手机号、邮箱、日期等字符串如何用声明式模式校验，并提取其中的结构化字段"的问题。'},{id:"J_16",title:"错误处理与自定义异常",navTitle:"错误处理",category:"语言基础",path:"/javascript/j-16/error-handling",summary:"用 try/catch/finally 和自定义 Error 类构建可恢复的错误流。",demo:null,demoComponent:Mt,code:Oo,language:"javascript",principle:"try/catch 捕获同步异常以及 async/await 中被拒绝的 Promise，finally 无论成败都执行清理；通过继承 Error 定义携带业务字段的异常子类，并可用 cause 选项把原始错误挂到新错误上形成错误链。同步与异步边界的失败统一汇入 try/catch 后，错误处理才能作为一等的设计对象。",flow:["用 try 包裹可能抛错的代码（如 JSON.parse、网络请求）。","在 catch 中按错误类型（或 err.name）分支处理。","用 finally 执行必达的清理逻辑，必要时包装错误并传入 cause。","构造一个自定义错误实例，验证 instanceof 能正确识别其类型。"],notes:["try/catch 捕获不到 setTimeout 等异步回调内部的同步抛出。","Error 构造器的 cause 选项（ES2022）可保留原始错误的引用。","建议依据错误类型分支处理，而不是仅解析 message 字符串。","Promise 链连续 then 时用最后的 catch 兜底，未处理的拒绝要配置全局监听。"],problem:'解决"如何在系统边界捕获异常、按错误类型分流处理，并用 cause 保留原始错误的上下文"的问题。'},{id:"J_17",title:"可选链、空值合并与逻辑赋值",navTitle:"可选链与空值合并",category:"语言基础",path:"/javascript/j-17/optional-nullish",summary:"安全访问深层属性、处理空值默认值和逻辑赋值运算符。",demo:null,demoComponent:Wt,code:Io,language:"javascript",principle:"可选链 ?. 在遇到 null/undefined 时短路并返回 undefined，避免抛出 TypeError；空值合并 ?? 只在左侧为 null/undefined 时取右侧；??=、||=、&&= 把“判断 + 赋值”合并成一步。",flow:["用 ?. 安全访问嵌套属性、可选索引与可选函数调用。","用 ?? 提供仅针对空值（null/undefined）的默认值。","用逻辑赋值运算符精简条件初始化。","对比 || 与 ?? 在 0、空字符串等 falsy 值上的差异。"],notes:["?? 与 || 的差别在于：|| 对空字符串和 0 等 falsy 值也会取右侧。","?. 与 ?? 都可单独使用，?.() 可安全调用可能不存在的函数。","可选链只对 null/undefined 短路，0、空字符串、false 等 falsy 值会继续向下访问。","?. 只保证读取安全；链末端是方法时记得带上调用括号 ?.()。"],problem:'解决"读取接口返回的深层字段时如何避免 undefined 报错，并只在真正空值时兜底默认值"的问题。'},{id:"J_18",title:"高阶函数、柯里化与组合",navTitle:"高阶函数",category:"函数与组合",path:"/javascript/j-18/higher-order",summary:"用函数组合构建价格计算器，掌握柯里化、偏函数和防抖节流。",demo:null,demoComponent:Ht,code:Vo,language:"javascript",principle:"高阶函数接收或返回函数；柯里化把多参函数拆为单参链，便于逐步配置；pipe/compose 把多个单步函数串联成流水线，让数据沿函数链流动；防抖和节流控制高频事件回调的执行频率，是 UI 交互和性能优化的常见工具。这几类函数本身不改变数据，只是重新组织函数的调度与组合方式。",flow:["用柯里化把多参数函数拆为单参链，边传参边形成配置。","用 pipe（从左到右）或 compose（从右到左）把单步函数串成处理流水线。","用防抖/节流包一层并返回新函数，控制高频事件的执行节奏。","为搜索框接入防抖，观察停止输入后才触发一次请求。"],notes:["Array.prototype.map、filter、reduce 本身就是高阶函数。","pipe 从左到右执行，compose 从右到左执行，混合使用时要注意顺序保持一致。","防抖在停手后才执行一次，节流保证一定间隔内至多执行一次。","防抖与节流都返回新函数；需要取消时记得保存返回值并调用其 cancel。"],problem:'解决"如何用函数组合替代重复代码，并用防抖节流控制高频事件的执行频率"的问题。'},{id:"J_19",title:"模板字面量与标签模板",navTitle:"模板字面量",category:"语言基础",path:"/javascript/j-19/template-literals",summary:"用标签模板实现文本高亮与 HTML 转义，掌握原始字符串和 DSL 构建。",demo:null,demoComponent:qt,code:go,language:"javascript",principle:"模板字面量用反引号书写，支持 ${} 插值与多行文本；标签模板把“字符串片段”与“插值结果”分离后交给标签函数，函数可在拼接前对每个插值做转义或包装。片段数组还保留了静态字符串信息，工具能据此解析模板结构，这正是 HTML 转义、文本高亮、CSS-in-JS、GraphQL 查询等 DSL 的实现基础。",flow:["用 ${} 在模板中嵌入任意表达式。","定义标签函数，第一个参数为字符串片段数组 strings，其余为插值 values。","用 String.raw 得到不处理转义符的原始字符串。","编写一个转义标签函数，验证插值中的特殊字符被处理。"],notes:["标签模板中字符串片段的数量 = 插值数量 + 1。","graphql-tag、styled-components 等都基于标签模板实现 DSL。","标签模板不会自动转义插值，直接拼进 HTML 仍有 XSS 风险，需要显式转义处理。","标签函数可通过 strings.raw 读取未转义的原始片段。"],problem:'解决"多行文本与插值如何组织，以及如何基于标签模板构建 HTML 转义、高亮等文本 DSL"的问题。'},{id:"J_20",title:"JSON 与结构化克隆",navTitle:"JSON 与克隆",category:"集合与数据",path:"/javascript/j-20/json-clone",summary:"用 replacer/reviver 控制序列化，用 structuredClone 深拷贝。",demo:null,demoComponent:tl,code:yo,language:"javascript",principle:"JSON.stringify 可通过 replacer（函数或数组）过滤并转换值，JSON.parse 的 reviver 在还原时重建类型；structuredClone 走结构化克隆算法，可深拷贝循环引用以及 Date、Map、Set、ArrayBuffer 等内置类型。",flow:["用 replacer 函数过滤字段、把 Date 序列化为字符串，或用 toJSON 自定义输出。","用 reviver 在解析时把日期字符串还原回 Date 实例。","对含循环引用的对象用 structuredClone 做深拷贝。","故意传入循环引用给 JSON.stringify，观察报错并用 structuredClone 解决。"],notes:["JSON 无法表示 undefined、函数、Symbol 与循环引用，Date 会退化为字符串。","structuredClone 能处理循环引用，但不支持函数与 DOM 节点。","序列化前先用 replacer 过滤密码、令牌等敏感字段，避免它们被写入存储或日志。","stringify 遇到 undefined、函数与 Symbol 属性会直接跳过，数组中则变成 null。"],problem:'解决"含 Date、循环引用的复杂对象如何正确序列化与深拷贝，并顺手过滤敏感字段"的问题。'},{id:"J_21",title:"属性描述符与对象控制",navTitle:"属性描述符",category:"对象模型",path:"/javascript/j-21/property-descriptors",summary:"用 defineProperty 精确控制属性行为，用 freeze/seal 锁定对象。",demo:null,demoComponent:ul,code:So,language:"javascript",principle:"每个自有属性的数据属性描述符含 configurable / enumerable / writable；存取属性描述符用 get / set 提供经过校验或计算的值；preventExtensions、seal、freeze 逐级收紧对对象增删改的限制。",flow:["用 defineProperty 精确设置单个属性的数据或存取描述符。","用 getter/setter 实现取值时计算与赋值校验（如拦截负数）。","按需用 preventExtensions / seal / freeze 锁定对象，防止意外修改。","用 getOwnPropertyDescriptor 检查 freeze 后属性的 writable 值。"],notes:["Object.freeze 只冻结一层，嵌套对象仍需递归处理。","Object.keys / values / entries 只覆盖可枚举的自有属性。","属性一旦设为 configurable: false，就再也无法删除或改回描述符配置。","getter 每次访问都会重新计算，开销大的值适合缓存而非每次求值。"],problem:'解决"如何让对象属性只读、不可枚举或改成计算属性，并用 freeze 锁定配置对象"的问题。'},{id:"J_22",title:"Symbol 与内置符号",navTitle:"Symbol",category:"语言基础",path:"/javascript/j-22/symbol",summary:"用 Symbol 实现唯一标识和自定义迭代，理解内置符号的作用。",demo:null,demoComponent:ml,code:bo,language:"javascript",principle:"Symbol 每次调用都生成独一无二的值，即使描述相同也不相等，适合作为不会冲突的属性键；内置符号（Symbol.iterator、Symbol.toPrimitive、Symbol.hasInstance 等）是语言约定的协议钩子，实现它们等于把对象接入 for...of、隐式类型转换、instanceof 等内建行为。",flow:["用 Symbol() 创建唯一的值，作为不冲突的属性键。","实现 Symbol.iterator 让对象可被 for...of 和展开消费。","用 Symbol.toPrimitive 控制对象在运算中的类型转换。","用两个描述相同的 Symbol 证明它们互不相等。"],notes:["Symbol.for 在全局注册表中按描述共享，Symbol.keyFor 可反向查询。","Symbol.hasInstance 可自定义 instanceof 行为，Symbol.toStringTag 自定义 toString 标签。","Symbol 属性不参与 for...in、Object.keys 与 JSON.stringify，天然适合存放不希望被序列化的元数据。","注册表符号用 Symbol.for 创建；重复调用会返回同一个值。"],problem:'解决"如何创建不冲突的属性键，并让自定义对象支持迭代、转换等内置行为"的问题。'},{id:"J_23",title:"字符串方法与国际化",navTitle:"字符串与 Intl",category:"语言基础",path:"/javascript/j-23/string-intl",summary:"用字符串方法搜索和转换文本，用 Intl 格式化日期和货币。",demo:null,demoComponent:pl,code:ho,language:"javascript",principle:"字符串方法覆盖搜索（includes、startsWith、matchAll）、截取（slice、at）、批量替换（replaceAll）、拆分（split）与填充修剪，且全部返回新字符串而不改动原串。Intl API 则提供地区感知的日期、数字、货币、相对时间与排序格式化，内部携带各地区的语言规则与数据，是国际化输出的标准方案，无需自己维护本地化词表。",flow:["用 includes、startsWith、matchAll 搜索文本和提取匹配。","用 replaceAll、slice、split 批量替换和拆分。","用 Intl.DateTimeFormat/NumberFormat 格式化输出并指定 locale。","用 Intl 格式化同一日期在两种 locale 下的输出，对比差异。"],notes:["字符串是不可变的，所有方法都返回新字符串。","Intl.Collator 可正确排序中文等多语言文本，胜过默认 < 运算。",'Intl.RelativeTimeFormat 输出"3 天前"等相对时间文案。',"matchAll 需要带 g 标志的正则，返回的是迭代器而非数组。"],problem:'解决"文本搜索与批量替换该用什么方法，以及日期、货币的地区化格式如何标准化输出"的问题。'},{id:"J_24",title:"逻辑运算、位运算与权限模型",navTitle:"逻辑与位运算",category:"语言基础",path:"/javascript/j-24/logical-bitwise",summary:"用位运算实现权限标志模型，掌握逻辑短路和赋值运算符。",demo:null,demoComponent:cl,code:Co,language:"javascript",principle:"逻辑运算符在结果已确定时立即短路，返回的不是布尔值而是参与运算的原始操作数，&&=、||=、??= 把“判断再赋值”合并为一步；位运算把操作数转换成 32 位有符号整数后逐位计算，因此可以用一个整数的不同二进制位并行编码多项权限或状态开关：用按位或 | 授予、按位与 & 检查、按位与非 &~ 撤销，存储与传输成本都远低于对象或数组。",flow:["用 &&、||、?? 做短路取值与默认值兜底。","用按位或 | 把多个权限标志合并进单个整数。","用按位与 & 检查权限、按位异或 ^ 切换权限位。","打印 5 & 3 等位运算结果，验证与二进制逐位对照的一致性。"],notes:["??=、||=、&&= 只在条件满足时才赋值，可简化默认值写法。","位运算以 32 位有符号整数为基准，超出范围会截断，需留意数值边界。","权限标志可用枚举或字面量常量定义，提升可读性。","权限常量用 2 的幂定义，读代码时按二进制展开即可对上每一位。"],problem:'解决"多个布尔权限如何合并进一个整数存储，并高效完成检查、授予与撤销操作"的问题。'},{id:"J_25",title:"Fetch API 与网络请求",navTitle:"Fetch API",category:"网络与通信",path:"/javascript/j-25/fetch-api",summary:"用 Fetch API 替代 XMLHttpRequest，掌握请求配置、响应处理和错误处理。",demo:null,demoComponent:yl,code:jo,language:"javascript",principle:"fetch() 返回 Promise，默认发起 GET 请求；可传 method、headers、body 等配置，也可复用 Request 对象；响应体须用 res.json() / res.text() 等方法读取，且一次 Response 只能读取一次。",flow:["配置 method、headers、body 后发起请求。","先检查 res.ok 判断状态码，非 2xx 时主动抛错。","用 res.json() 解析响应体，并从 res.headers / res.status 读取元信息。","用浏览器网络面板确认请求方法与请求头与代码配置一致。"],notes:['跨域请求默认不带 Cookie，需设置 credentials: "include"；同源请求默认携带。',"HTTP 错误状态码不会让 fetch reject，须手动检查 res.ok 再决定是否抛错。","fetch 没有内置超时，需要配合 AbortController 手动中止超时的请求。","需要二次读取响应体时先克隆：const copy = res.clone()。"],problem:'解决"如何以现代方式发起网络请求、区分 HTTP 错误与网络失败，并正确读取响应体"的问题。'},{id:"J_26",title:"Web Storage 与 IndexedDB",navTitle:"Web Storage",category:"存储",path:"/javascript/j-26/web-storage",summary:"用 localStorage/sessionStorage 存储简单键值，用 IndexedDB 存储大量结构化数据。",demo:null,demoComponent:Jl,code:xo,language:"javascript",principle:'localStorage 持久化保存、跨会话可用，sessionStorage 以标签页为单位、关闭即清除；两者都只能存字符串，存对象需 JSON 序列化；IndexedDB 提供异步的事务化大容量结构化存储与索引查询。选型时按"生命周期、容量、同步性"三个维度对照，即可快速决策。',flow:["用 localStorage 持久化跨会话的用户偏好。","用 sessionStorage 暂存当前标签页的表单进度。","数据量大或结构复杂时用基于事务的 IndexedDB 存取。","在 devtools 应用面板确认写入的键值与代码预期一致。"],notes:['storage 事件只在"其他"同源标签页触发，当前页不会收到自身变更。',"IndexedDB 是异步的、基于事务，数据放在对象仓库（object store）中。","写入超出存储配额会抛出 QuotaExceededError，写入前应估算体积并处理该异常。","localStorage 同步读写会阻塞主线程，大批量数据应改用 IndexedDB。"],problem:'解决"浏览器端如何持久化用户偏好与表单进度，以及不同存储方案各自适用什么场景"的问题。'},{id:"J_27",title:"WebSocket 与实时通信",navTitle:"WebSocket",category:"网络与通信",path:"/javascript/j-27/websocket",summary:"用 WebSocket 建立持久双向连接，理解与服务端推送（SSE）的差异。",demo:null,demoComponent:Hl,code:Jo,language:"javascript",principle:"WebSocket 在 HTTP 升级握手后建立一条持久连接，客户端与服务端可随时双向发送数据；SSE（Server-Sent Events）则是一条普通 HTTP 长连接，通过 text/event-stream 由服务端单向推送，二者用途不同。",flow:["创建 WebSocket 实例并监听 open / message / close 等事件。","连接建立后通过 ws.send() 随时发送消息，消息经 ws.onmessage 接收。","对比 WebSocket 的全双工与 SSE 的服务端单向推送，选择合适方案。","用浏览器网络面板分别查看 WebSocket 帧与 SSE 的事件流。"],notes:["WebSocket 使用 ws:// 与 wss://（TLS）协议前缀。","onmessage 里 event.data 为字符串，JSON 数据需自行解析；回调中的 this 需要用箭头函数捕获。","生产环境建议处理重连、心跳与消息队列。","SSE 的 EventSource 自带断线重连，WebSocket 需要自行实现重连逻辑。"],problem:'解决"如何实现服务端主动向客户端推送数据，以及实时双向通信的方案选择"的问题。'},{id:"J_28",title:"AbortController 与可中断操作",navTitle:"AbortController",category:"异步控制",path:"/javascript/j-28/abort-controller",summary:"用 AbortController 取消进行中的 Fetch 请求、事件监听和其他可中断操作。",demo:null,demoComponent:to,code:wo,language:"javascript",principle:"AbortController 持有 signal，异步 API 可通过 signal 订阅取消信号；调用 controller.abort() 会派发 signal 的 abort 事件并使 signal.aborted 变为 true，Fetch、addEventListener 等均已原生支持 signal。",flow:["创建 AbortController 并取出其 signal。","把 signal 传入 fetch 配置，或作为事件监听的 options.signal。","在需要时调用 controller.abort()，fetch 会以 AbortError 拒绝、带 signal 的监听被移除。","连续输入触发两次请求，验证前一次被 abort 后不会覆盖新结果。"],notes:["同一个 signal 可同时关联多个请求或事件监听，一次 abort() 全部取消。","调用 abort() 后 signal.aborted 变为 true，并触发所有订阅的 abort 监听器。","取消会让 fetch 以 AbortError 拒绝，需要与真实的网络失败区分处理，避免误报错误提示。","abort() 后同一 signal 便处于终止态，需要新请求时重新创建控制器。"],problem:'解决"搜索联想等场景下如何取消过期的网络请求与事件监听，避免旧结果覆盖新结果"的问题。'}];export{$o as lessons};
